local CheeseDomeMaker = {}
local PRODUCTS = {
    iron_cheesedome = { name = "Železni klopot za sir", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni klopot za sir za kuharje." },
    bronze_cheesedome = { name = "Bronast klopot za sir", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast klopot za sir za kuharje." },
    silver_cheesedome = { name = "Srebrn klopot za sir", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn klopot za sir za kuharje." },
    gilded_cheesedome = { name = "Pozlačen klopot za sir", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen klopot za sir za kuharje." },
    jewel_set_cheesedome = { name = "Draguljast klopot za sir", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast klopot za sir za kuharje." },
    royal_sovereign_cheesedome = { name = "Kraljevski suveren klopot za sir", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren klopot za sir z biseri za krono." },
}
local BUILDINGS = {
    cheesedome_workshop = { name = "Cheesedome delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    cheesedome_house = { name = "Cheesedome hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_cheesedome_atelier = { name = "Mojstrski cheesedome atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_cheesedome_palace = { name = "Suverena cheesedome palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
CheeseDomeMaker.ironStock=14; CheeseDomeMaker.bronzeStock=12; CheeseDomeMaker.woodStock=12; CheeseDomeMaker.leatherStock=8; CheeseDomeMaker.silverStock=8; CheeseDomeMaker.goldStock=6; CheeseDomeMaker.jewelStock=4; CheeseDomeMaker.pearlStock=4
CheeseDomeMaker.productStock = {}; CheeseDomeMaker.buildings = {}; CheeseDomeMaker.maker = nil; CheeseDomeMaker.activeMaking = {}; CheeseDomeMaker.totalProducts = 0; CheeseDomeMaker.dayTimer = 0
function CheeseDomeMaker.init() CheeseDomeMaker.ironStock=14; CheeseDomeMaker.bronzeStock=12; CheeseDomeMaker.woodStock=12; CheeseDomeMaker.leatherStock=8; CheeseDomeMaker.silverStock=8; CheeseDomeMaker.goldStock=6; CheeseDomeMaker.jewelStock=4; CheeseDomeMaker.pearlStock=4; CheeseDomeMaker.productStock={}; CheeseDomeMaker.buildings={}; CheeseDomeMaker.maker=nil; CheeseDomeMaker.activeMaking={}; CheeseDomeMaker.totalProducts=0; CheeseDomeMaker.dayTimer=0; print("[CheeseDomeMaker] Royal Cheese Dome Maker System initialized (6 products, 4 buildings)") end
function CheeseDomeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CheeseDomeMaker.maker={name=n or ("Klopotar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klopotar najet: %s (spretnost: %d)",CheeseDomeMaker.maker.name,s),"success") end; return true end
function CheeseDomeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CheeseDomeMaker.build(id) local ok,e=CheeseDomeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CheeseDomeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CheeseDomeMaker.getQualityBonus() local b=0; for _,bd in ipairs(CheeseDomeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CheeseDomeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CheeseDomeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CheeseDomeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CheeseDomeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CheeseDomeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CheeseDomeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CheeseDomeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CheeseDomeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CheeseDomeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CheeseDomeMaker.buildings==0 then return false,"Potrebna klopotna delavnica" end; if not CheeseDomeMaker.maker then return false,"Potreben klopotar" end; return true end
function CheeseDomeMaker.make(pt,qty) qty=qty or 1; local ok,e=CheeseDomeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CheeseDomeMaker.ironStock=CheeseDomeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CheeseDomeMaker.bronzeStock=CheeseDomeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CheeseDomeMaker.woodStock=CheeseDomeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CheeseDomeMaker.leatherStock=CheeseDomeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CheeseDomeMaker.silverStock=CheeseDomeMaker.silverStock-d.silverCost*qty end; if d.goldCost then CheeseDomeMaker.goldStock=CheeseDomeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CheeseDomeMaker.jewelStock=CheeseDomeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CheeseDomeMaker.pearlStock=CheeseDomeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CheeseDomeMaker.maker then t=math.max(1,t-math.floor(CheeseDomeMaker.maker.skill/13)) end; table.insert(CheeseDomeMaker.activeMaking,{id="cheesedome_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CheeseDomeMaker.completeMaking(m) local q=1.0+(CheeseDomeMaker.getQualityBonus()/100); if CheeseDomeMaker.maker then q=q+(CheeseDomeMaker.maker.skill/140) end; q=math.min(2.5,q); CheeseDomeMaker.productStock[m.productType]=(CheeseDomeMaker.productStock[m.productType] or 0)+m.quantity; CheeseDomeMaker.totalProducts=CheeseDomeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CheeseDomeMaker.maker then CheeseDomeMaker.maker.itemsMade=CheeseDomeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CheeseDomeMaker.maker.skill=math.min(100,CheeseDomeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klopot izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cheesedome.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CheeseDomeMaker.update(dt) if not _G.state then return end; CheeseDomeMaker.dayTimer=CheeseDomeMaker.dayTimer+dt; if CheeseDomeMaker.dayTimer>=30 then CheeseDomeMaker.dayTimer=0; for i=#CheeseDomeMaker.activeMaking,1,-1 do local m=CheeseDomeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CheeseDomeMaker.completeMaking(m); table.remove(CheeseDomeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CheeseDomeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CheeseDomeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CheeseDomeMaker.getStats() return {ironStock=CheeseDomeMaker.ironStock,bronzeStock=CheeseDomeMaker.bronzeStock,woodStock=CheeseDomeMaker.woodStock,leatherStock=CheeseDomeMaker.leatherStock,silverStock=CheeseDomeMaker.silverStock,goldStock=CheeseDomeMaker.goldStock,jewelStock=CheeseDomeMaker.jewelStock,pearlStock=CheeseDomeMaker.pearlStock,productStock=CheeseDomeMaker.productStock,numBuildings=#CheeseDomeMaker.buildings,hasMaker=CheeseDomeMaker.maker~=nil,makerName=CheeseDomeMaker.maker and CheeseDomeMaker.maker.name or "—",makerSkill=CheeseDomeMaker.maker and CheeseDomeMaker.maker.skill or 0,activeMaking=#CheeseDomeMaker.activeMaking,totalProducts=CheeseDomeMaker.totalProducts} end
return CheeseDomeMaker
